SELECT IFNULL(SUM(overtime_hours), 0)
FROM biz_overtime_record
WHERE del_flag = 0
  AND confirm_status = 1
  AND staff_id = #{staffId}
  AND overtime_date = #{overtimeDate}

SELECT project_id AS projectId, IFNULL(SUM(overtime_hours), 0) AS overtimeHours FROM biz_overtime_record WHERE del_flag = 0 AND confirm_status = 1 AND project_id IN
#{projectId}
GROUP BY project_id
